   FROM steps,LATERAL (SELECT raw#>ARRAY['information',st->>'id'] i) info),'{}'::jsonb),
  'turns','[]'::jsonb,'plans','[]'::jsonb,'handoffs','[]'::jsonb,'report',NULL::jsonb) END
